def investigate(context, acquire):
    capacity = context['capacity']
    events = context['events']
    order = []
    present = set()
    hits = 0
    misses = 0
    for event in events:
        if event['op'] == 'reset':
            order = []
            present = set()
            hits = 0
            misses = 0
        else:
            key = event['key']
            if key in present:
                hits = hits + 1
                order.remove(key)
                order.append(key)
            else:
                misses = misses + 1
                if len(order) == capacity:
                    present.discard(order.pop(0))
                order.append(key)
                present.add(key)
    return {'hits': hits, 'misses': misses, 'size': len(order)}

